/* ======================= PESTAÑAS PRINCIPALES ======================= */
/* 15/09/2026 — con la fusión de "Mapa y capas" + "Ficha técnica", el mapa es
   ahora la pestaña por defecto: lo inicializamos ya al cargar la página, en
   vez de esperar a un primer clic sobre una pestaña que ya no existe. */
document.addEventListener('DOMContentLoaded', () => {
  if (!window.calleMapInitDone) { window.calleMapInitDone = true; initCalleMap(); }
});

/* 15/09/2026 — acordeón de la Ficha técnica: cada campo empieza cerrado y
   se abre/cierra al clicar su cabecera, sin afectar a los valores que
   escribe initCalleMap() en los mismos <span id="ficha-...">. */
document.addEventListener('DOMContentLoaded', () => {
  document.querySelectorAll('.ficha-acordeon .ficha-cabecera').forEach((btn) => {
    btn.addEventListener('click', () => {
      const item = btn.closest('.ficha-acordeon');
      const abierto = item.getAttribute('data-abierto') === 'true';
      item.setAttribute('data-abierto', abierto ? 'false' : 'true');
    });
  });
});

document.querySelectorAll('.tab-btn').forEach((btn) => {
  btn.addEventListener('click', () => {
    document.querySelectorAll('.tab-btn').forEach((b) => b.classList.remove('active'));
    document.querySelectorAll('.panel').forEach((p) => p.classList.remove('active'));
    btn.classList.add('active');
    document.getElementById(btn.dataset.panel).classList.add('active');
    if (btn.dataset.panel === 'panel-calle') {
      if (!window.calleMapInitDone) { window.calleMapInitDone = true; initCalleMap(); }
      else if (window.calleMap) setTimeout(() => window.calleMap.invalidateSize(), 50);
    }
  });
});

