/* ======================= VISTA DE CALLE (mapa propio + muñequito arrastrable) ======================= */
/* ======================= EXPORT DE TERRA (fusionado en el mapa propio) =======================
   15/09/2026 — antes esto vivía en un <iframe src="mapa_resultados_....html"> aparte, en su
   propia pestaña "Mapa y capas". Ahora se carga aquí, dentro del mismo mapa Leaflet que ya usa
   el muñequito/Ficha técnica: terra_layers.js reutiliza window.mapaTerraPropio en vez de crear
   un mapa nuevo. Las librerías se cargan en orden estricto porque terra_layers.js las necesita
   ya disponibles (leaflet.draw, leaflet-measure, MousePosition, awesome-markers, el botón de
   captura PNG/PDF y jsPDF). */
function cargarScriptsSecuencial(urls, alTerminar) {
  let i = 0;
  function siguiente() {
    if (i >= urls.length) { alTerminar(); return; }
    const s = document.createElement('script');
    s.src = urls[i++];
    s.onload = siguiente;
    s.onerror = function () {
      console.error('No se pudo cargar el script del export TERRA:', s.src);
      siguiente(); // seguimos con el resto para no bloquear todo el visor
    };
    document.head.appendChild(s);
  }
  siguiente();
}

function cargarExportTerra() {
  if (window.terraExportCargado) return;
  window.terraExportCargado = true;
  const dependencias = [
    'https://code.jquery.com/jquery-3.7.1.min.js',
    'https://cdn.jsdelivr.net/npm/bootstrap@5.2.2/dist/js/bootstrap.bundle.min.js',
    'https://cdnjs.cloudflare.com/ajax/libs/Leaflet.awesome-markers/2.0.2/leaflet.awesome-markers.js',
    'https://cdn.jsdelivr.net/gh/ljagis/leaflet-measure@2.1.7/dist/leaflet-measure.min.js',
    'https://cdn.jsdelivr.net/gh/ardhi/Leaflet.MousePosition/src/L.Control.MousePosition.min.js',
    'https://cdnjs.cloudflare.com/ajax/libs/leaflet.draw/1.0.2/leaflet.draw.js',
    'https://unpkg.com/leaflet-simple-map-screenshoter@0.5.0/dist/leaflet-simple-map-screenshoter.js',
    'https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js',
    'terra_layers.js'
  ];
  cargarScriptsSecuencial(dependencias, function () {
    console.log('Export TERRA cargado y enganchado al mapa propio.');
  });
}

