/* ======================= CIELO ESTRELLADO (Panel de datos y FAQ) =======================
   15/09/2026 — mismo efecto visual que la web: estrellas que parpadean a ritmo
   distinto + estrellas fugaces cruzando de vez en cuando. Se genera una vez por
   contenedor y se queda fijo detrás del contenido (position:absolute, z-index:0). */
function generarCieloEstrellado(idContenedor, numEstrellas) {
  const cont = document.getElementById(idContenedor);
  if (!cont || cont.dataset.generado) return;
  cont.dataset.generado = '1';

  for (let i = 0; i < numEstrellas; i++) {
    const e = document.createElement('div');
    e.className = 'estrella';
    const tam = (Math.random() * 2 + 0.6).toFixed(1);
    e.style.width = tam + 'px';
    e.style.height = tam + 'px';
    e.style.top = (Math.random() * 100).toFixed(2) + '%';
    e.style.left = (Math.random() * 100).toFixed(2) + '%';
    e.style.setProperty('--op-min', (Math.random() * 0.25 + 0.05).toFixed(2));
    e.style.setProperty('--op-max', (Math.random() * 0.4 + 0.6).toFixed(2));
    e.style.animationDuration = (Math.random() * 3 + 2).toFixed(2) + 's';
    e.style.animationDelay = (Math.random() * 4).toFixed(2) + 's';
    cont.appendChild(e);
  }

  function lanzarEstrellaFugaz() {
    if (!document.body.contains(cont)) return;
    const f = document.createElement('div');
    f.className = 'estrella-fugaz';
    const inicioX = Math.random() * 70 + 5;
    const inicioY = Math.random() * 40 + 5;
    const dx = Math.random() * 220 + 140;
    const dy = Math.random() * 110 + 60;
    f.style.top = inicioY + '%';
    f.style.left = inicioX + '%';
    f.style.setProperty('--dx', dx + 'px');
    f.style.setProperty('--dy', dy + 'px');
    f.style.setProperty('--angulo', (Math.atan2(dy, dx) * 180 / Math.PI) + 'deg');
    cont.appendChild(f);
    setTimeout(() => f.remove(), 1500);
    setTimeout(lanzarEstrellaFugaz, Math.random() * 6000 + 4000);
  }
  setTimeout(lanzarEstrellaFugaz, Math.random() * 3000 + 1500);
}

document.addEventListener('DOMContentLoaded', () => {
  generarCieloEstrellado('cielo-panel-demo', 140);
  generarCieloEstrellado('cielo-panel-faq', 100);
});
